import Foundation

/// Generated by `scripts/worker_catalog/build_worker_catalog.py`.
struct WorkerModelCatalog: Codable, Equatable, Sendable {
    let version: Int
    let generated: String
    let categories: [String]
    let attribution: [String]
    let estimates: WorkerEstimateTunables
    let models: [WorkerBaseModel]

    static let empty = WorkerModelCatalog(
        version: 1,
        generated: "",
        categories: ["general"],
        attribution: [],
        estimates: .default,
        models: []
    )

    static let bundled: WorkerModelCatalog = {
        let resourceBundles = [Bundle.main, Bundle(for: BundleLocator.self)]
        guard let url = resourceBundles.lazy.compactMap({
            $0.url(forResource: "WorkerModelCatalog", withExtension: "json")
        }).first,
            let data = try? Data(contentsOf: url)
        else {
            return .empty
        }
        return load(from: data)
    }()

    static func load(from data: Data) -> WorkerModelCatalog {
        (try? JSONDecoder().decode(WorkerModelCatalog.self, from: data)) ?? .empty
    }

    private final class BundleLocator {}
}

struct WorkerBaseModel: Codable, Equatable, Sendable {
    let baseID: String
    let totalParams: Double
    let activeParams: Double
    let kvBytesPerToken: Int64
    let modality: String
    let scores: [String: WorkerCategoryScore]
    let variants: [WorkerVariant]
}

struct WorkerCategoryScore: Codable, Equatable, Sendable {
    /// Mark out of 100 on the category's one test; only comparable within the category.
    let score: Double
    let sources: [WorkerScoreSource]
}

struct WorkerScoreSource: Codable, Equatable, Sendable {
    let benchmark: String
    let raw: Double
    let source: String
    let url: String?
}

struct WorkerVariant: Codable, Equatable, Sendable {
    let repoID: String
    let bits: Double
    let sizeBytes: Int64
    let downloads: Int
    let supportsTools: Bool
}

struct WorkerSizePenalty: Codable, Equatable, Sendable {
    let maxParams: Double?
    let penalty: Double
}

/// Penalties are the percent of a score lost to quantization.
struct WorkerEstimateTunables: Codable, Equatable, Sendable {
    let bandwidthEfficiency: Double
    let speedBucketFloors: [Double]
    let penaltyHighBit: Double
    let penaltySixBit: Double
    let fourBitPenalties: [WorkerSizePenalty]
    let lowBitFactor: Double

    static let `default` = WorkerEstimateTunables(
        bandwidthEfficiency: 0.6,
        speedBucketFloors: [80, 30, 10],
        penaltyHighBit: 0.5,
        penaltySixBit: 1,
        fourBitPenalties: [
            WorkerSizePenalty(maxParams: 1, penalty: 15),
            WorkerSizePenalty(maxParams: 2, penalty: 8),
            WorkerSizePenalty(maxParams: 5, penalty: 4),
            WorkerSizePenalty(maxParams: 15, penalty: 2),
            WorkerSizePenalty(maxParams: nil, penalty: 1),
        ],
        lowBitFactor: 2
    )
}
